import{_ as e,c as o,o as l,ag as i}from"./chunks/framework.B3RpK1bM.js";const u=JSON.parse('{"title":"代码编写规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/code-writing-specifications.md","filePath":"zh_CN/code-writing-specifications.md","lastUpdated":1769658044000}'),t={name:"zh_CN/code-writing-specifications.md"};function c(r,a,d,s,h,n){return l(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="代码编写规范" tabindex="-1">代码编写规范 <a class="header-anchor" href="#代码编写规范" aria-label="Permalink to &quot;代码编写规范&quot;">​</a></h1><p><a href="./">返回目录</a></p><h2 id="godot" tabindex="-1">Godot <a class="header-anchor" href="#godot" aria-label="Permalink to &quot;Godot&quot;">​</a></h2><h3 id="场景" tabindex="-1">场景 <a class="header-anchor" href="#场景" aria-label="Permalink to &quot;场景&quot;">​</a></h3><p>场景初步定义<strong>展示场景</strong>与<strong>功能场景</strong>概念.</p><h4 id="场景基础规范" tabindex="-1">场景基础规范 <a class="header-anchor" href="#场景基础规范" aria-label="Permalink to &quot;场景基础规范&quot;">​</a></h4><ul><li>场景应该统一存储在<code>./scene</code>文件夹下</li><li>场景命名统一采用驼峰命名法</li><li>场景根节点应该与场景名称相同</li></ul><h4 id="展示场景" tabindex="-1">展示场景 <a class="header-anchor" href="#展示场景" aria-label="Permalink to &quot;展示场景&quot;">​</a></h4><p><strong>展示场景</strong>为需要直接跳转的场景，比如<code>main.tscn</code>场景、<code>game.tscn</code>场景、<code>end.tscn</code>场景，展示场景的基础规范如下：</p><ul><li>根节点只管理基础控制操作</li></ul><h4 id="功能场景" tabindex="-1">功能场景 <a class="header-anchor" href="#功能场景" aria-label="Permalink to &quot;功能场景&quot;">​</a></h4><p><strong>功能场景</strong>指通过添加以实现某种对应功能的场景，比如<code>bottom.tscn</code>场景、<code>font.tscn</code>场景，功能场景的基础规范如下：</p><ul><li>一个功能场景只实现一个业务操作</li><li>功能场景不应该直接继承<code>./theme</code>文件夹内的主题，应该通过所在的展示场景继承.</li></ul><h3 id="节点" tabindex="-1">节点 <a class="header-anchor" href="#节点" aria-label="Permalink to &quot;节点&quot;">​</a></h3><h4 id="节点基础规范" tabindex="-1">节点基础规范 <a class="header-anchor" href="#节点基础规范" aria-label="Permalink to &quot;节点基础规范&quot;">​</a></h4><ul><li>节点应该统一使用驼峰命名法.</li></ul><h2 id="csharp" tabindex="-1">Csharp <a class="header-anchor" href="#csharp" aria-label="Permalink to &quot;Csharp&quot;">​</a></h2><p>csharp文件应该统一存储在<code>./ezgal/csharp</code>文件夹中.</p><h3 id="csharp基础规范" tabindex="-1">csharp基础规范 <a class="header-anchor" href="#csharp基础规范" aria-label="Permalink to &quot;csharp基础规范&quot;">​</a></h3><ul><li>文件名称应该与继承的节点名称对应采用驼峰命名法.</li><li>变量命名规范如下所示: <ul><li>全局共有变量(public)采用大驼峰命名法(<code>CamelCase</code>).</li><li>全局私有变量(private)采用首位下划线的小驼峰命名法(<code>_camelCase</code>).</li><li>函数内部变量采用小驼峰命名法(<code>camelCase</code>).</li><li>需要获取节点时应注意变量名与获取的节点名称对应.</li><li>如果变量对应单一节点需添加<code>Node</code>后缀.</li><li>如果变量对应场景需添加<code>Scene</code>后缀.</li><li>如果变量对应路径需添加<code>Path</code>后缀.</li></ul></li><li>函数采用大驼峰命名法.</li><li>复杂函数应采用<code>&lt;summary&gt;&lt;/summary&gt;</code>简洁地说明函数的意义, 说明语言推荐统一采用<strong>英文-中文-日文</strong>的顺序.</li></ul><h3 id="全局文件" tabindex="-1">全局文件 <a class="header-anchor" href="#全局文件" aria-label="Permalink to &quot;全局文件&quot;">​</a></h3><p>当前csharp使用的全局文件包含<code>FlowData.cs</code>、<code>Global.cs</code>、<code>Tools.cs</code>.</p><h5 id="flowdata" tabindex="-1">FlowData <a class="header-anchor" href="#flowdata" aria-label="Permalink to &quot;FlowData&quot;">​</a></h5><p><code>FlowData.cs</code>文件为深度开发的核心定义文件，应尽量避免修改，如果<code>FlowData.cs</code>文件出现变动，需要调整make文件夹内部文件使其符合构建要求.</p><h5 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h5><p><code>Global.cs</code>文件用于存储ezgal的解释器函数，非解释功能内容请勿添加在<code>Global.cs</code>.</p><h5 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h5><p>用于存储复用性较高的函数与相关参数.</p><h2 id="gdscript" tabindex="-1">gdscript <a class="header-anchor" href="#gdscript" aria-label="Permalink to &quot;gdscript&quot;">​</a></h2><p>gdscript文件应该统一存储在<code>./ezgal/gdscript</code>文件夹中.</p><h4 id="gdscript基础规范" tabindex="-1">gdscript基础规范 <a class="header-anchor" href="#gdscript基础规范" aria-label="Permalink to &quot;gdscript基础规范&quot;">​</a></h4><ul><li>变量、函数应采用蛇形命名法(<code>snake_case</code>).</li><li>需要获取节点时应注意变量名与获取的节点名称对应.</li><li>如果变量对应单一节点需添加<code>_node</code>后缀.</li><li>如果变量对应场景需添加<code>_scene</code>后缀.</li><li>函数应注明变量类型、返还变量类型.</li></ul><h4 id="全局文件-1" tabindex="-1">全局文件 <a class="header-anchor" href="#全局文件-1" aria-label="Permalink to &quot;全局文件&quot;">​</a></h4><h5 id="ezapi" tabindex="-1">ezapi <a class="header-anchor" href="#ezapi" aria-label="Permalink to &quot;ezapi&quot;">​</a></h5><p><code>ezapi</code>是使用gdscript调用csharp方法的统一接口.</p>',35)])])}const b=e(t,[["render",c]]);export{u as __pageData,b as default};
